#include <bits/stdc++.h>
using namespace std;

bool areVectorsEqual(const long long a[], const long long b[]) {
    for (int i = 0; i < 5; i++) {
        if (a[i] != b[i]) return false;
    }
    return true;
}

bool isDotPositive(const long long a[], const long long b[]) {
    long long sum = 0;
    for (int i = 0; i < 5; i++) {
        sum += a[i] * b[i];
    }
    return sum > 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int total;
    cin >> total;
    if (total <= 11) {
        vector<array<long long, 5>> pointsData(total);
        for (int i = 0; i < total; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> pointsData[i][j];
            }
        }

        vector<vector<array<long long, 5>>> vectorsArray(total, vector<array<long long, 5>>(total));
        for (int i = 0; i < total; i++) {
            for (int j = 0; j < total; j++) {
                for (int k = 0; k < 5; k++) {
                    vectorsArray[i][j][k] = pointsData[j][k] - pointsData[i][k];
                }
            }
        }

        unordered_set<int> excludedIndices;

        for (int i = 0; i < total; i++) {
            bool breakFlag = false;
            for (int j = 0; j < total; j++) {
                for (int k = 0; k < total; k++) {
                    if (!areVectorsEqual(vectorsArray[i][j].data(), vectorsArray[i][k].data()) && isDotPositive(vectorsArray[i][j].data(), vectorsArray[i][k].data())) {
                        excludedIndices.insert(i + 1);
                        breakFlag = true;
                        break;
                    }
                }
                if (breakFlag) break;
            }
        }

        cout << total - (int)excludedIndices.size() << "\n";
        for (int i = 0; i < total; i++) {
            if (excludedIndices.find(i + 1) == excludedIndices.end()) {
                cout << i + 1 << "\n";
            }
        }
    } else {
        cout << 0 << "\n";
    }
    return 0;
}
